+type Word = { text: string; prefix: string; quoted: boolean };
+
+const KEYWORDS = new Set(['{', '}', '!', 'if', 'then', 'else', 'elif', 'fi', 'do', 'done', 'while', 'until']);
+const SHELLS = new Set(['bash', 'sh', 'zsh', 'dash', 'ksh']);
+const ASSIGNMENT = /^[A-Za-z_][A-Za-z0-9_]*=/;
+const ONLY_REDIRECT = /^(\d*(<<<|<<|<>|<&|<|>>|>&|>\||>)|&>>?)$/;
+const STARTS_REDIRECT = /^(\d*[<>]|&>)/;
+
+// Scans `s` from `i` until `term` (or the end), appending each simple command to `out`. Returns the index after
+// the terminator, or null on unbalanced quotes.
+function parse(s: string, i: number, term: ')' | '`' | null, out: string[][]): number | null {
+  let words: Word[] = [];
+  let nested: string[][] = [];
+  let text = '';
+  let prefix = '';
+  let quoted = false;
+  let started = false;
+  let depth = 0;
+  const add = (c: string, isQuoted: boolean) => {
+    text += c;
+    if (isQuoted) quoted = true;
+    else if (!quoted) prefix += c;
+    started = true;
+  };
+  const endWord = () => {
+    if (started) words.push({ text, prefix, quoted });
+    text = prefix = '';
+    quoted = started = false;
+  };
+  const endCommand = (): boolean => {
+    endWord();
+    const commands = finish(words);
+    if (commands === null) return false;
+    out.push(...commands, ...nested);
+    words = [];
+    nested = [];
+    return true;
+  };
+  const sub = (start: number, t: ')' | '`'): boolean => {
+    const r = parse(s, start, t, nested);
+    if (r === null) return false;
+    i = r;
+    return true;
+  };
+
+  while (i < s.length) {
+    const c = s[i];
+    if ((c === '`' && term === '`') || (c === ')' && term === ')' && depth === 0)) {
+      return endCommand() ? i + 1 : null;
+    }
+    if (c === '\\') {
+      if (s[i + 1] === '\n') i += 2;
+      else if (i + 1 < s.length) { add(s[i + 1], true); i += 2; }
+      else { add(c, false); i++; }
+    } else if (c === "'") {
+      const j = s.indexOf("'", i + 1);
+      if (j < 0) return null;
+      add(s.slice(i + 1, j), true);
+      i = j + 1;
+    } else if (c === '"') {
+      add('', true);
+      i++;
+      for (;;) {
+        if (i >= s.length) return null;
+        const d = s[i];
+        if (d === '"') { i++; break; }
+        if (d === '\\' && i + 1 < s.length) { add(s[i + 1], true); i += 2; }
+        else if (d === '$' && s[i + 1] === '(') { if (!sub(i + 2, ')')) return null; }
+        else if (d === '`') { if (!sub(i + 1, '`')) return null; }
+        else { add(d, true); i++; }
+      }
+    } else if (c === '$' && s[i + 1] === '(') {
+      if (!sub(i + 2, ')')) return null;
+    } else if (c === '`') {
+      if (!sub(i + 1, '`')) return null;
+    } else if (c === ' ' || c === '\t' || c === '\r') {
+      endWord();
+      i++;
+    } else if (c === '\n' || c === ';' || c === '|' || c === '(' || c === ')') {
+      if (c === '(') depth++;
+      if (c === ')' && depth > 0) depth--;
+      if (!endCommand()) return null;
+      i += c === '|' && (s[i + 1] === '|' || s[i + 1] === '&') ? 2 : 1;
+    } else if (c === '&') {
+      if (s[i + 1] === '&') {
+        if (!endCommand()) return null;
+        i += 2;
+      } else if (s[i + 1] === '>' || (started && !quoted && /[<>]$/.test(text))) {
+        add(c, false);
+        i++;
+      } else {
+        if (!endCommand()) return null;
+        i++;
+      }
+    } else if (c === '<' || c === '>') {
+      // `cmd>out` is the word `cmd` followed by the redirection `>out`; `2>`, `&>` and `>>` stay one word.
+      if (started && (quoted || !/^[\d&]*[<>]*$/.test(text))) endWord();
+      add(c, false);
+      i++;
+    } else {
+      add(c, false);
+      i++;
+    }
+  }
