+}
+
+// Drops redirections, assignments, keywords and wrappers from one simple command, and unpacks `bash -c` and `eval`.
+function finish(words: Word[]): string[][] | null {
+  const argv: string[] = [];
+  for (let k = 0; k < words.length; k++) {
+    const w = words[k];
+    if (!w.quoted && ONLY_REDIRECT.test(w.text)) k++;
+    else if (!STARTS_REDIRECT.test(w.prefix)) argv.push(w.text);
+  }
+  let k = 0;
+  while (k < argv.length) {
+    if (ASSIGNMENT.test(argv[k]) || KEYWORDS.has(argv[k])) { k++; continue; }
+    const wrapper = WRAPPERS.get(basename(argv[k]));
+    if (!wrapper) break;
+    k++;
+    while (k < argv.length && argv[k].startsWith('-')) {
+      const flag = argv[k++];
+      if (flag === '--') break;
+      if (wrapper.value?.includes(flag)) k++;
+    }
+    k += wrapper.positional ?? 0;
+  }
+  const rest = argv.slice(k);
+  if (rest.length === 0) return [];
+  const name = basename(rest[0]);
+  if (SHELLS.has(name)) {
+    const c = rest.findIndex((a, ix) => ix > 0 && /^-[A-Za-z]*c[A-Za-z]*$/.test(a));
+    const script = c < 0 ? undefined : rest.slice(c + 1).find((a) => !a.startsWith('-'));
+    if (script !== undefined) return simpleCommands(script);
+  }
+  if (name === 'eval') return simpleCommands(rest.slice(1).join(' '));
+  return [rest];
+}
+
+function basename(word: string): string {
+  return word.slice(word.lastIndexOf('/') + 1);
