+  let words: Word[] = [];
+  let word: Word | null = null;
+  let subs: Word[][] = [];
+  let depth = 0;
+  const endWord = () => {
+    if (word) words.push(word);
+    word = null;
+  };
+  const endCommand = () => {
+    endWord();
+    if (words.length) out.push(words);
+    out.push(...subs);
+    words = [];
+    subs = [];
+  };
