+    const { text, plain } = words[i];
+    if (plain && REDIRECT_ONLY.test(text)) i++;
+    else if (!(plain && REDIRECT_PREFIX.test(text))) args.push(text);
+  }
+  let i = 0;
+  while (i < args.length && (ASSIGNMENT.test(args[i]) || KEYWORDS.has(args[i]))) i++;
+  return args.slice(i);
