+
+// Unwraps wrappers, shells running -c scripts and eval; returns the commands the argv really runs.
+function unwrap(args: string[]): string[][] | null {
+  for (;;) {
+    if (args.length === 0) return [];
+    const name = args[0].slice(args[0].lastIndexOf('/') + 1);
+    const wrapper = WRAPPERS.get(name);
+    if (wrapper) {
+      let i = 1;
+      while (i < args.length && args[i].startsWith('-')) {
+        if (args[i] === '--') {
+          i++;
+          break;
+        }
+        i += wrapper.value?.includes(args[i]) ? 2 : 1;
+      }
+      i += wrapper.positional ?? 0;
+      args = args.slice(i);
+      let j = 0;
+      while (j < args.length && ASSIGNMENT.test(args[j])) j++;
+      args = args.slice(j);
+      continue;
+    }
+    if (name === 'eval') return simpleCommands(args.slice(1).join(' '));
+    if (SHELLS.has(name)) {
+      let i = 1;
+      let script = false;
+      while (i < args.length && args[i].startsWith('-') && args[i] !== '--') {
+        if (/^-[A-Za-z]*c/.test(args[i])) script = true;
+        i++;
+      }
+      if (script && i < args.length) return simpleCommands(args[i]);
+    }
+    return [args];
+  }
